CREATE OR REPLACE FUNCTION private.neutralize_premature_invoice_posting_flags()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  mode text := coalesce(private.finance_audit_posting_guard_mode(), 'observe');
  premature_transition boolean;
begin
  if mode = 'off'
     or coalesce(new.data_environment, 'production') <> 'production'
     or new.voided_at is not null
     or private.finance_invoice_fully_approved(new.steps) then
    return new;
  end if;

  premature_transition :=
    (coalesce(old.revenue_posted, false) = false and coalesce(new.revenue_posted, false) = true)
    or (old.revenue_posted_at is null and new.revenue_posted_at is not null)
    or (
      old.posting_locked_at is null and new.posting_locked_at is not null
      and coalesce(new.revenue_posted, false) = true
    );

  if premature_transition then
    perform private.record_finance_guard_event(
      'invoice_premature_flag_neutralized:' || new.id,
      'invoice_premature_flag_neutralized', mode, 'invoice', new.id, new.no,
      jsonb_build_object(
        'approval_status', new.approval_status,
        'legacy_revenue_posted', new.revenue_posted,
        'legacy_revenue_posted_at', new.revenue_posted_at
      ), new.tenant_id
    );

    new.revenue_posted := old.revenue_posted;
    new.revenue_posted_at := old.revenue_posted_at;
    if old.posting_locked_at is null then
      new.posting_locked_at := null;
    end if;
    new.revenue_posting_state := case
      when coalesce(old.revenue_posted, false) then old.revenue_posting_state
      else 'deferred'
    end;
    new.revenue_posting_error := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.post_invoice_revenue_after_final_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  mode text := coalesce(private.finance_audit_posting_guard_mode(), 'observe');
begin
  if mode = 'off'
     or coalesce(new.data_environment, 'production') <> 'production'
     or new.voided_at is not null
     or coalesce(new.revenue_posted, false) then
    return new;
  end if;

  if private.finance_invoice_fully_approved(new.steps)
     and not private.finance_invoice_fully_approved(old.steps) then
    begin
      perform private.post_invoice_revenue_v2_internal(new.id, true);
    exception when others then
      perform private.record_finance_guard_event(
        'invoice_final_posting_failed:' || new.id,
        'invoice_final_posting_failed', mode, 'invoice', new.id, new.no,
        jsonb_build_object('error', sqlerrm, 'sqlstate', sqlstate), new.tenant_id
      );
      update public.invoices
      set revenue_posting_state = 'pending_accounting_review',
          revenue_posting_error = left(sqlerrm, 1000),
          updated_at = now()
      where id = new.id;
    end;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_accounting_ledger_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  mode text := coalesce(private.finance_audit_posting_guard_mode(), 'observe');
  inv public.invoices%rowtype;
  req public.expense_requests%rowtype;
begin
  if mode = 'off' or coalesce(new.data_environment, 'production') <> 'production' then
    return new;
  end if;

  if coalesce(new.source_type, '') = 'invoice'
     and coalesce(new.posting_key, '') like 'invoice:%:revenue:%' then
    select * into inv
    from public.invoices i
    where i.id::text = new.source_id
       or i.no = coalesce(new.source_no, new.reference_no)
    order by case when i.id::text = new.source_id then 0 else 1 end
    limit 1;

    if found and not private.finance_invoice_fully_approved(inv.steps) then
      perform private.record_finance_guard_event(
        'invoice_ledger_before_final:' || coalesce(new.posting_key, inv.id),
        'invoice_ledger_before_final', mode, 'invoice', inv.id, inv.no,
        jsonb_build_object('posting_key', new.posting_key), inv.tenant_id
      );
      if mode = 'enforce' then
        raise exception '發票 % 尚未完成全部簽核，不可寫入收入分類帳。', inv.no
          using errcode = '23514';
      end if;
    end if;
  end if;

  if coalesce(new.source_type, '') in ('expense_request', 'expense_requests')
     and new.account_code = '1144'
     and coalesce(new.debit, 0) > 0 then
    select * into req
    from public.expense_requests r
    where r.id::text = new.source_id
       or r.no = coalesce(new.source_no, new.reference_no)
    order by case when r.id::text = new.source_id then 0 else 1 end
    limit 1;

    if found and req.type = 'hr_expense_request' then
      perform private.record_finance_guard_event(
        'hr_input_tax_ledger:' || coalesce(new.posting_key, req.id),
        'hr_input_tax_ledger', mode, 'expense_request', req.id, req.no,
        jsonb_build_object('amount', new.debit, 'account_code', new.account_code), req.tenant_id
      );
      if mode = 'enforce' then
        raise exception '人事費用申請 % 不得自動列入 1144 進項稅額，請覆核人事費用科目。', req.no
          using errcode = '23514';
      end if;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_finance_invoice_source_chain()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if coalesce(new.source_type, '') in ('invoice', 'invoice_reversal')
     or coalesce(new.posting_key, '') like 'invoice:%' then
    begin
      perform private.refresh_finance_invoice_source_chain_one(new.id);
    exception when others then
      raise warning 'invoice source-chain sync skipped for ledger_entry_id=%: %', new.id, sqlerrm;
    end;
  end if;
  return new;
end;
$function$

