CREATE OR REPLACE FUNCTION public.prevent_posted_voucher_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE') and old.posted = true and old.voided_at is null then
    raise exception 'Posted vouchers are immutable; create a reversal or adjustment voucher instead.';
  end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_posted_ledger_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE') and old.posting_key is not null and old.voided_at is null then
    raise exception 'Posted ledger entries are immutable; create a reversal or adjustment voucher instead.';
  end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_history_search_text_v1(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s text; m text[];
begin
 s:=lower(normalize(coalesce(p_value,''),NFKC));
 s:=btrim(regexp_replace(replace(s,'−','-'),'[[:space:]]+',' ','g'));
 s:=regexp_replace(s,'(?:nt\$|ntd|twd|新臺幣|新台幣|\$)\s*([+-]?\d[\d,]*(?:\.\d+)?)','\1','g');
 s:=regexp_replace(s,'(\d)\s*元','\1','g');
 -- A comma-free value cannot contain thousands groups.
 if position(',' in s)>0 then
 for m in select regexp_matches(s,'(^|[^\d,])([+-]?\d{1,3}(?:,\d{3})+)(?![\d,])','g') loop
  s:=replace(s,m[1]||m[2],m[1]||replace(m[2],',',''));
 end loop;
 end if;
 return s;
end;
$function$

