CREATE OR REPLACE FUNCTION private.finance_wake_notification_worker()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'vault', 'net'
AS $function$
declare
  v_worker_url text;
  v_worker_secret text;
  v_worker_anon_key text;
  v_request_id bigint;
begin
  select decrypted_secret
  into v_worker_url
  from vault.decrypted_secrets
  where name = 'finance_notification_worker_url'
  order by created_at desc
  limit 1;

  select decrypted_secret
  into v_worker_secret
  from vault.decrypted_secrets
  where name = 'finance_notification_worker_secret'
  order by created_at desc
  limit 1;

  select decrypted_secret
  into v_worker_anon_key
  from vault.decrypted_secrets
  where name = 'finance_notification_worker_anon_key'
  order by created_at desc
  limit 1;

  if nullif(trim(v_worker_url), '') is null
    or nullif(trim(v_worker_secret), '') is null
    or nullif(trim(v_worker_anon_key), '') is null then
    return null;
  end if;

  select net.http_post(
    url := trim(v_worker_url),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || trim(v_worker_anon_key),
      'apikey', trim(v_worker_anon_key),
      'x-finance-worker-secret', trim(v_worker_secret)
    ),
    body := jsonb_build_object(
      'limit', 50,
      'worker_id', 'database-' || pg_backend_pid()::text
    ),
    timeout_milliseconds := 15000
  ) into v_request_id;

  return v_request_id;
exception
  when others then
    raise warning 'Unable to wake finance notification worker: %', sqlerrm;
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.rebuild_approval_step_actor_snapshots(p_record_type text, p_record_id text, p_record_no text, p_steps jsonb, p_data_environment text, p_entity_id text, p_department_code text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenants uuid[];
  v_tenant_id uuid;
  v_current_tenant uuid;
  v_environment text := coalesce(nullif(p_data_environment, ''), 'production');
begin
  if p_record_id is null then
    return 0;
  end if;

  case p_record_type
    when 'expense_requests' then
      select pg_catalog.array_agg(distinct source_row.tenant_id)
        into v_tenants
      from public.expense_requests source_row
      where source_row.id = p_record_id
        and source_row.data_environment = v_environment;
    when 'invoices' then
      select pg_catalog.array_agg(distinct source_row.tenant_id)
        into v_tenants
      from public.invoices source_row
      where source_row.id = p_record_id
        and source_row.data_environment = v_environment;
    when 'bills' then
      select pg_catalog.array_agg(distinct source_row.tenant_id)
        into v_tenants
      from public.bills source_row
      where source_row.id = p_record_id
        and source_row.data_environment = v_environment;
    else
      raise exception 'Unsupported approval snapshot record type: %', p_record_type
        using errcode = '22023';
  end case;

  if coalesce(pg_catalog.cardinality(v_tenants), 0) = 0 then
    return 0;
  elsif pg_catalog.cardinality(v_tenants) = 1 then
    v_tenant_id := v_tenants[1];
  else
    v_current_tenant := public.current_tenant_id();
    if v_current_tenant = any(v_tenants) then
      v_tenant_id := v_current_tenant;
    else
      raise exception 'Approval snapshot source is ambiguous across tenants'
        using errcode = '21000';
    end if;
  end if;

  return private.rebuild_approval_step_actor_snapshots(
    p_record_type,
    p_record_id,
    p_record_no,
    p_steps,
    v_environment,
    p_entity_id,
    p_department_code,
    v_tenant_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_bill_admin_and_income_closure()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
