CREATE OR REPLACE FUNCTION private.finance_attachment_issue_count(p_record_type text, p_record_keys text[])
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'storage', 'pg_temp'
AS $function$
declare
  v_count int := 0;
begin
  if p_record_keys is null or array_length(p_record_keys, 1) is null then
    return 0;
  end if;

  select count(*)::int
  into v_count
  from public.finance_attachment_integrity_issues() i
  where (
    i.record_no = any (p_record_keys)
    or (
      i.record_type = p_record_type
      and i.record_no = any (p_record_keys)
    )
    or (
      i.record_no is null
      and exists (
        select 1
        from unnest(p_record_keys) k
        where k is not null and i.storage_path like '%' || k || '%'
      )
    )
  );

  return coalesce(v_count, 0);
exception when undefined_function then
  return 0;
end;
$function$

