CREATE OR REPLACE FUNCTION private.finance_require_authenticated_tenant()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_finance_user public.finance_users%rowtype;
begin
  if auth.uid() is null then
    raise exception '請先登入後再執行帳務作業'
      using errcode = '42501';
  end if;

  v_tenant_id := public.current_tenant_id();
  v_finance_user := public.current_finance_user();

  if v_tenant_id is null
     or v_finance_user.id is null
     or v_finance_user.tenant_id is distinct from v_tenant_id
     or v_finance_user.auth_user_id is distinct from auth.uid()
     or v_finance_user.active is not true then
    raise exception '目前 Google 登入身分沒有此租戶的有效財務帳號'
      using errcode = '42501';
  end if;

  return v_tenant_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_attachment_source_identity_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_exists boolean;begin
 if tg_table_schema<>'public' or tg_table_name not in ('expense_requests','invoices','bills','vouchers') then
  raise exception 'Invalid attachment source identity trigger' using errcode='42501';
 end if;
 if tg_op='UPDATE' and new.id is distinct from old.id then
  raise exception '單據內部識別碼不可修改' using errcode='23514';
 end if;
 if tg_op='INSERT' and exists(select 1 from private.finance_legacy_attachment_links_v1 l
   where l.record_type=tg_table_name and l.parent_key=new.id) then
  execute format('select exists(select 1 from public.%I where id=$1)',tg_table_name) into source_exists using new.id;
  if not source_exists then raise exception '已封存附件的單據識別碼不可重複使用' using errcode='23514';end if;
 end if;
 return new;
end
$function$

CREATE OR REPLACE FUNCTION private.finance_enqueue_current_approval_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_row jsonb := to_jsonb(new);
  v_tenant_text text;
  v_tenant_id uuid;
  v_environment text;
  v_source_status text;
  v_source_id text;
  v_source_group_id text;
  v_source_no text;
  v_source_label text;
  v_step_number integer;
  v_steps jsonb;
  v_current_step jsonb;
  v_role_key text;
  v_role_label text;
  v_recipient_id text;
  v_recipient_name text;
  v_recipient_email text;
  v_assignment_key text;
  v_generation integer;
  v_event_id text;
  v_inserted_count integer := 0;
  v_group_still_pending boolean := false;
begin
  v_source_id := nullif(trim(v_row ->> 'id'), '');
  v_tenant_text := nullif(trim(v_row ->> 'tenant_id'), '');
  v_environment := lower(nullif(trim(v_row ->> 'data_environment'), ''));

  -- Tenant and environment are authorization boundaries. Never infer either
  -- one for a notification, even if a legacy default exists on the table.
  if v_source_id is null or v_tenant_text is null or v_environment is null then
    return new;
  end if;

  begin
    v_tenant_id := v_tenant_text::uuid;
  exception
    when invalid_text_representation then
      return new;
  end;

  v_source_group_id := coalesce(nullif(trim(v_row ->> 'batch_id'), ''), v_source_id);
  v_source_status := lower(coalesce(
    nullif(v_row ->> 'approval_status', ''),
    nullif(v_row ->> 'status', ''),
    ''
  ));
  v_step_number := case
    when coalesce(v_row ->> 'approval_step', v_row ->> 'step', '') ~ '^[0-9]+$'
      then coalesce(v_row ->> 'approval_step', v_row ->> 'step')::integer
    else 0
  end;
  v_steps := coalesce(v_row -> 'steps', '[]'::jsonb);
  v_current_step := case
    when jsonb_typeof(v_steps) = 'array'
      and v_step_number between 1 and jsonb_array_length(v_steps)
      then v_steps -> (v_step_number - 1)
    else null
  end;

  if v_environment <> 'production'
    or v_source_status not like 'pending%'
    or v_current_step is null
    or nullif(trim(coalesce(v_current_step ->> 'a', '')), '') is not null then
    if tg_table_name in ('invoices', 'bills') and v_environment = 'production' then
      execute format(
        'select exists (
           select 1
           from public.%I r
           where coalesce(nullif(r.batch_id::text, ''''), r.id::text) = $1
             and r.id::text <> $2
             and r.tenant_id = $3
             and r.data_environment = $4
             and lower(coalesce(nullif(r.approval_status, ''''), r.status, '''')) like ''pending%%''
         )',
        tg_table_name
      )
      into v_group_still_pending
      using v_source_group_id, v_source_id, v_tenant_id, v_environment;
    end if;

    if not v_group_still_pending then
      delete from private.approval_notification_assignment_state
      where tenant_id = v_tenant_id
        and data_environment = v_environment
        and source_table = tg_table_name
        and source_group_id = v_source_group_id;
    end if;
    return new;
  end if;

  v_recipient_id := nullif(trim(coalesce(v_current_step ->> 'uid', '')), '');
  if v_recipient_id is null then
    return new;
  end if;

  select u.name, lower(trim(u.email))
  into v_recipient_name, v_recipient_email
  from public.finance_users u
  where u.id = v_recipient_id
    and u.tenant_id = v_tenant_id
    and u.active is not false
  limit 1;

  if v_recipient_email is null
    or v_recipient_email !~* '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then
    return new;
  end if;

  v_role_key := coalesce(nullif(v_current_step ->> 'rk', ''), 'approver');
  v_role_label := coalesce(
    nullif(v_current_step ->> 'r', ''),
    nullif(v_current_step ->> 'label', ''),
    '簽核人'
  );
  v_assignment_key := concat_ws('|', v_step_number::text, v_recipient_id, v_role_key);

  insert into private.approval_notification_assignment_state (
    tenant_id,
    data_environment,
    source_table,
    source_group_id,
    source_record_id,
    assignment_key,
    assignment_generation,
    recipient_finance_user_id,
    updated_at
  ) values (
    v_tenant_id,
    v_environment,
    tg_table_name,
    v_source_group_id,
    v_source_id,
    v_assignment_key,
    1,
    v_recipient_id,
    now()
  )
  on conflict (tenant_id, data_environment, source_table, source_group_id)
  do update set
    source_record_id = excluded.source_record_id,
    assignment_key = excluded.assignment_key,
    assignment_generation = private.approval_notification_assignment_state.assignment_generation + 1,
    recipient_finance_user_id = excluded.recipient_finance_user_id,
    notification_event_id = null,
    updated_at = now()
  where private.approval_notification_assignment_state.assignment_key
    is distinct from excluded.assignment_key
  returning assignment_generation into v_generation;

  if v_generation is null then
    return new;
  end if;

  v_source_no := coalesce(
    nullif(trim(v_row ->> 'no'), ''),
    nullif(trim(v_row ->> 'request_no'), ''),
    v_source_id
  );
  v_source_label := case
    when tg_table_name = 'invoices' then '發票申請'
    when tg_table_name = 'bills' then '繳費單申請'
    when coalesce(v_row ->> 'type', '') = 'shareholder_transaction' then '股東／公司往來申請'
    else '支出申請'
  end;
  v_event_id := 'nde_approval_' || substr(md5(concat_ws(
    '|',
    v_tenant_id::text,
    v_environment,
    tg_table_name,
    v_source_group_id,
    v_assignment_key,
    v_generation::text
  )), 1, 28);

  insert into public.notification_delivery_events (
    id,
    event_type,
    title,
    body,
    request_id,
    channels,
    status,
    payload,
    data_environment,
    tenant_id,
    next_retry_at,
    max_attempts
  ) values (
    v_event_id,
    'approval_task_assigned',
    '待您簽核｜' || v_source_no || '｜' || v_role_label,
    coalesce(nullif(v_recipient_name, ''), '同仁')
      || '您好，您已收到一筆新的' || v_source_label || '簽核待辦，目前關卡為「'
      || v_role_label || '」。請儘速登入歲悅財務系統完成簽核，以利流程進入下一關。',
    v_source_no,
    array['email']::text[],
    'pending',
    jsonb_build_object(
      'template', 'approval_task_assigned_v2',
      'direct_link_version', 2,
      'recipient_emails', jsonb_build_array(v_recipient_email),
      'recipient_name', coalesce(v_recipient_name, ''),
      'recipient_finance_user_id', v_recipient_id,
      'source_table', tg_table_name,
      'source_id', v_source_id,
      'source_group_id', v_source_group_id,
      'source_no', v_source_no,
      'source_label', v_source_label,
      'tenant_id', v_tenant_id::text,
      'data_environment', v_environment,
      'entity_id', coalesce(v_row ->> 'entity_id', ''),
      'applicant', coalesce(v_row ->> 'applicant', ''),
      'amount', coalesce(v_row ->> 'amount', v_row ->> 'total', ''),
      'approval_step', v_step_number,
      'approval_role_key', v_role_key,
      'approval_role_label', v_role_label,
      'assignment_generation', v_generation,
      'app_url', 'https://finance.suiyuecare.com/'
    ),
    v_environment,
    v_tenant_id,
    now(),
    20
  )
  on conflict (id) do nothing;

  get diagnostics v_inserted_count = row_count;
  if v_inserted_count = 0 and not exists (
    select 1
    from public.notification_delivery_events existing
    where existing.id = v_event_id
      and existing.event_type = 'approval_task_assigned'
      and existing.tenant_id = v_tenant_id
      and existing.data_environment = v_environment
      and existing.request_id = v_source_no
      and existing.payload ->> 'source_table' = tg_table_name
      and existing.payload ->> 'source_id' = v_source_id
      and existing.payload ->> 'source_group_id' = v_source_group_id
      and existing.payload ->> 'source_no' = v_source_no
      and existing.payload ->> 'recipient_finance_user_id' = v_recipient_id
      and existing.payload -> 'recipient_emails' = jsonb_build_array(v_recipient_email)
  ) then
    raise exception using
      errcode = 'PNA01',
      message = format(
        'Reserved approval notification id collision for %s',
        v_event_id
      ),
      hint = 'Do not retry the business action until the conflicting event has been investigated.';
  end if;

  update private.approval_notification_assignment_state
  set notification_event_id = v_event_id,
      updated_at = now()
  where tenant_id = v_tenant_id
    and data_environment = v_environment
    and source_table = tg_table_name
    and source_group_id = v_source_group_id
    and assignment_generation = v_generation;

  begin
    perform private.finance_wake_notification_worker();
  exception
    when others then
      raise warning 'Approval email queued but worker wake failed: %', sqlerrm;
  end;

  return new;
exception
  when sqlstate 'PNA01' then
    -- A deterministic id collision is a security incident. Never let the
    -- trigger's best-effort fallback hide it or silently lose the email.
    raise;
  when others then
    raise warning 'Approval email enqueue skipped for %.%: %', tg_table_name, coalesce(v_source_id, '?'), sqlerrm;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_invoice_admin_and_income_closure()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  begin
    perform private.upsert_invoice_admin_director_bottleneck(new.id);
  exception when others then
    raise warning 'admin director bottleneck sync skipped for invoice_id=%: %', new.id, sqlerrm;
  end;

  begin
    perform private.upsert_invoice_income_closure(new.id);
  exception when others then
    raise warning 'income closure sync skipped for invoice_id=%: %', new.id, sqlerrm;
  end;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_role_binding_status(p_env text, p_role_key text, p_user_id text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  m public.approval_role_responsibility_matrix%rowtype;
  u public.finance_users%rowtype;
begin
  if coalesce(p_user_id, '') = '' then
    return 'missing_assignee';
  end if;

  select *
  into m
  from public.approval_role_responsibility_matrix
  where data_environment = coalesce(nullif(p_env, ''), 'production')
    and role_key = p_role_key;

  select *
  into u
  from public.finance_users
  where id = p_user_id;

  if not found then
    return 'unknown_assignee';
  end if;

  if not coalesce(u.active, false) then
    return 'inactive_assignee';
  end if;

  if coalesce(u.role, '') <> p_role_key then
    return 'role_mismatch';
  end if;

  if m.primary_user_id is not null and p_user_id = m.primary_user_id then
    return 'primary_admin_director';
  end if;

  if p_user_id = any (coalesce(m.fallback_user_ids, '{}'::text[])) then
    return 'documented_fallback';
  end if;

  return 'non_primary_admin_director';
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_receivable_status(p_source_table text, p_source_id text, p_paid_at timestamp with time zone, p_status text, p_voided_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  f public.collection_followups%rowtype;
  v_is_paid boolean := p_paid_at is not null or coalesce(p_status, '') = 'paid';
  v_is_voided boolean := p_voided_at is not null or coalesce(p_status, '') in ('voided', 'cancelled');
begin
  if v_is_voided then
    return jsonb_build_object(
      'receivable_closure_status', 'voided',
      'payment_status', 'voided',
      'followup_status', null,
      'followup_stage', null
    );
  end if;

  select *
  into f
  from public.collection_followups
  where source_table = p_source_table
    and source_id = p_source_id
  limit 1;

  if not found then
    return jsonb_build_object(
      'receivable_closure_status', case when v_is_paid then 'paid_confirmed' else 'receivable_missing_followup' end,
      'payment_status', case when v_is_paid then 'paid' else 'unpaid' end,
      'followup_status', null,
      'followup_stage', null
    );
  end if;

  return jsonb_build_object(
    'receivable_closure_status', case
      when f.payment_status = 'paid' or v_is_paid then 'paid_confirmed'
      when f.payment_status = 'voided' then 'voided'
      else 'receivable_open'
    end,
    'payment_status', f.payment_status,
    'followup_status', f.followup_status,
    'followup_stage', f.followup_stage,
    'followup_id', f.id
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_income_validate_scope(p_tenant_id uuid, p_entity_id text, p_department_code text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_entity_name text;
begin
  if coalesce(pg_catalog.btrim(p_entity_id), '') = '' then
    raise exception '請選擇法人' using errcode = '22023';
  end if;
  if coalesce(pg_catalog.btrim(p_department_code), '') = '' then
    raise exception '請選擇部門' using errcode = '22023';
  end if;

  select coalesce(
           nullif(entity_item ->> 'full', ''),
           nullif(entity_item ->> 's', ''),
           p_entity_id
         )
    into v_entity_name
  from public.system_settings setting_row
  cross join lateral pg_catalog.jsonb_array_elements(setting_row.value)
    entity_item
  where setting_row.tenant_id = p_tenant_id
    and setting_row.key = 'entities'
    and pg_catalog.upper(pg_catalog.btrim(entity_item ->> 'id')) =
        pg_catalog.upper(pg_catalog.btrim(p_entity_id))
  limit 1;

  if v_entity_name is null then
    raise exception '所選法人不存在或不屬於目前租戶：%', p_entity_id
      using errcode = '23503';
  end if;

  perform private.finance_assert_form_department_scope(
    p_tenant_id,
    p_department_code,
    p_entity_id,
    null,
    null
  );

  return v_entity_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.current_finance_user()
 RETURNS finance_users
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth_user_id uuid := auth.uid();
  v_tenant_id uuid;
  v_verified_email text;
  v_user public.finance_users%rowtype;
begin
  if v_auth_user_id is null or not public.finance_auth_session_active() then
    return null;
  end if;

  v_verified_email := public.finance_verified_google_email(v_auth_user_id);
  if v_verified_email is null then
    return null;
  end if;

  v_tenant_id := public.current_tenant_id();
  if v_tenant_id is null then
    return null;
  end if;

  select fu.*
  into v_user
  from public.finance_users fu
  where fu.tenant_id = v_tenant_id
    and fu.active = true
    and fu.auth_user_id = v_auth_user_id
    and fu.google_link_status in ('bound', 'pending_rebind')
    and lower(pg_catalog.btrim(fu.email)) = v_verified_email
  order by fu.created_at asc, fu.id asc
  limit 1;

  return v_user;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_income_begin_operation(p_tenant_id uuid, p_data_environment text, p_operation_type text, p_idempotency_key text, p_request_digest text, p_actor_finance_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_operation private.finance_income_document_operations%rowtype;
begin
  if coalesce(p_idempotency_key, '') !~
    '^[A-Za-z0-9][A-Za-z0-9._:-]{7,199}$' then
    raise exception
      '冪等鍵格式錯誤：請使用 8 到 200 字元的英數、句點、底線、冒號或連字號'
      using errcode = '22023';
  end if;

  insert into private.finance_income_document_operations (
    tenant_id, data_environment, operation_type, idempotency_key,
    request_digest, actor_finance_user_id
  )
  values (
    p_tenant_id, p_data_environment, p_operation_type, p_idempotency_key,
    p_request_digest, p_actor_finance_user_id
  )
  on conflict (tenant_id, data_environment, operation_type, idempotency_key)
  do nothing;

  select operation_row.*
    into v_operation
  from private.finance_income_document_operations operation_row
  where operation_row.tenant_id = p_tenant_id
    and operation_row.data_environment = p_data_environment
    and operation_row.operation_type = p_operation_type
    and operation_row.idempotency_key = p_idempotency_key
  for update;

  if not found then
    raise exception '無法鎖定表單操作紀錄'
      using errcode = '55000';
  end if;

  -- Do not expose a prior actor's result or allow a canceled request to race
  -- in after reconciliation has proved that no submit transaction committed.
  if v_operation.actor_finance_user_id is distinct from p_actor_finance_user_id then
    raise exception '此冪等鍵屬於另一位使用者'
      using errcode = '42501';
  end if;
  if v_operation.operation_status = 'canceled' then
    raise exception '此送件識別碼已確認未成立；請用保留的表單重新送件'
      using errcode = '55000';
  end if;
  if v_operation.request_digest is distinct from p_request_digest then
    raise exception '相同冪等鍵已使用於不同內容，請產生新的冪等鍵'
      using errcode = '23505';
  end if;
  if v_operation.operation_status = 'completed' then
    return v_operation.result;
  end if;
  if v_operation.operation_status <> 'in_progress' then
    raise exception '表單操作紀錄狀態異常'
      using errcode = '55000';
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_income_validate_submission_steps(p_steps jsonb, p_actor_finance_user_id text, p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_step jsonb;
  v_index int;
  v_role_key text;
  v_user_id text;
  v_action text;
  v_pending_index int;
  v_pending_status text;
  v_first jsonb;
  v_first_role text;
  v_first_user text;
  v_first_action text;
begin
  if pg_catalog.jsonb_typeof(p_steps) <> 'array'
     or pg_catalog.jsonb_array_length(p_steps) < 2
     or pg_catalog.jsonb_array_length(p_steps) > 30 then
    raise exception '簽核流程必須包含 2 到 30 個步驟'
      using errcode = '22023';
  end if;

  v_first := p_steps -> 0;
  v_first_role := pg_catalog.lower(coalesce(
    nullif(v_first ->> 'rk', ''),
    nullif(v_first ->> 'role_key', ''),
    nullif(v_first ->> 'roleKey', ''),
    ''
  ));
  v_first_user := coalesce(
    nullif(v_first ->> 'uid', ''),
    nullif(v_first ->> 'user_id', ''),
    nullif(v_first ->> 'finance_user_id', ''),
    ''
  );
  v_first_action := pg_catalog.lower(coalesce(v_first ->> 'a', ''));

  if v_first_role <> 'applicant_submit'
     or v_first_user <> p_actor_finance_user_id
     or v_first_action <> 'approved' then
    raise exception
      '簽核流程第一關必須是目前申請人已完成的 applicant_submit'
      using errcode = '22023';
  end if;

  for v_step, v_index in
    select step_value, ordinality::int
    from pg_catalog.jsonb_array_elements(p_steps)
      with ordinality as step_rows(step_value, ordinality)
  loop
    if pg_catalog.jsonb_typeof(v_step) <> 'object' then
      raise exception '第 % 個簽核步驟格式錯誤', v_index
        using errcode = '22023';
    end if;

    v_role_key := pg_catalog.lower(coalesce(
      nullif(v_step ->> 'rk', ''),
      nullif(v_step ->> 'role_key', ''),
      nullif(v_step ->> 'roleKey', ''),
      nullif(v_step ->> 'role', ''),
      ''
    ));
    v_user_id := coalesce(
      nullif(v_step ->> 'uid', ''),
      nullif(v_step ->> 'user_id', ''),
      nullif(v_step ->> 'userId', ''),
      nullif(v_step ->> 'finance_user_id', ''),
      ''
    );
    v_action := pg_catalog.lower(coalesce(v_step ->> 'a', ''));

    if v_index > 1 and v_action <> '' and not (
      v_action in ('approved', 'auto')
      and pg_catalog.lower(coalesce(v_step ->> 'autoSkip', 'false')) = 'true'
      and coalesce(v_step ->> 'autoSkipReason', '') <> ''
    ) then
      raise exception '送出時第 % 個簽核步驟不得預先完成', v_index
        using errcode = '22023';
    end if;

    if v_index > 1 and v_user_id <> '' and not exists (
      select 1
      from public.finance_users finance_user
      where finance_user.tenant_id = p_tenant_id
        and finance_user.id = v_user_id
        and finance_user.active is true
    ) then
      raise exception '第 % 個簽核步驟指定的人員不存在或已停用', v_index
        using errcode = '23503';
    end if;

    if v_index > 1
       and v_user_id = ''
       and v_role_key not in (
         'accountant',
         'accountant_final',
         'accountant_invoice',
         'cashier',
         'ceo',
         'admin_director',
         'general_affairs',
         'hr'
       ) then
      raise exception '第 % 個簽核步驟缺少明確簽核人', v_index
        using errcode = '22023';
    end if;

    if v_pending_index is null and v_action = '' then
      v_pending_index := v_index;
      v_pending_status := coalesce(
        nullif(v_step ->> 'status', ''),
        'pending_approval'
      );

      if v_user_id = p_actor_finance_user_id
         and v_role_key not in (
           'applicant_revision',
           'applicant_confirm',
           'applicant_invoice_delivery'
         ) then
        raise exception '送出後第一個待簽人不得是申請人本人'
          using errcode = '22023';
      end if;
    end if;
  end loop;

  if v_pending_index is null then
    raise exception '送出流程至少要有一個待簽步驟'
      using errcode = '22023';
  end if;

  return pg_catalog.jsonb_build_object(
    'steps', p_steps,
    'approval_status', v_pending_status,
    'approval_step', v_pending_index
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_bump_approval_row_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    -- Never trust a caller-supplied initial version, including direct table
    -- INSERTs allowed by RLS.  Every new source row starts at version 1.
    new.row_version := 1;
    return new;
  end if;

  if old.row_version >= 9223372036854775807::bigint then
    raise exception 'Approval source row version is exhausted'
      using errcode = '54000';
  end if;

  new.row_version := old.row_version + 1;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_submit_invoice_batch(p_idempotency_key text, p_items jsonb, p_data_environment text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_actor public.finance_users%rowtype;
  v_environment text := pg_catalog.lower(coalesce(p_data_environment, 'production'));
  v_digest text;
  v_cached jsonb;
  v_item jsonb;
  v_item_index int;
  v_item_key text;
  v_entity_id text;
  v_entity_name text;
  v_department_code text;
  v_amount numeric;
  v_tax numeric;
  v_total numeric;
  v_invoice_date date;
  v_identifier_type text;
  v_route jsonb;
  v_steps jsonb;
  v_seq bigint;
  v_batch_seq bigint;
  v_period text := pg_catalog.to_char(current_date, 'YYYYMM');
  v_tenant_token text;
  v_id text;
  v_no text;
  v_batch_id text;
  v_result_rows jsonb := '[]'::jsonb;
  v_result jsonb;
  v_source_bill_id text;
begin
  if auth.uid() is null then
    raise exception '請先登入後再送出發票'
      using errcode = '42501';
  end if;
  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test'
      using errcode = '22023';
  end if;

  v_tenant_id := public.current_tenant_id();
  select finance_user.*
    into v_actor
  from public.finance_users finance_user
  where finance_user.tenant_id = v_tenant_id
    and finance_user.auth_user_id = auth.uid()
    and finance_user.active is true
  order by finance_user.created_at, finance_user.id
  limit 1;

  if not found then
    raise exception '目前登入帳號沒有此租戶的有效財務人員身分'
      using errcode = '42501';
  end if;

  perform private.finance_income_assert_items_with_limit(p_items, 500);
  v_digest := private.finance_income_request_digest(
    pg_catalog.jsonb_build_object(
      'operation', 'invoice_submit',
      'environment', v_environment,
      'items', p_items
    )
  );
  v_cached := private.finance_income_begin_operation(
    v_tenant_id,
    v_environment,
    'invoice_submit',
    p_idempotency_key,
    v_digest,
    v_actor.id
  );
  if v_cached is not null then
    return v_cached || pg_catalog.jsonb_build_object(
      'idempotent_replay',
      true
    );
  end if;

  v_tenant_token := pg_catalog.replace(
    pg_catalog.left(v_tenant_id::text, 8),
    '-',
    ''
  );

  if pg_catalog.jsonb_array_length(p_items) > 1 then
    v_batch_seq := private.finance_income_next_number(
      v_tenant_id,
      v_environment,
      'invoice_batch',
      v_period
    );
    v_batch_id := case
      when v_environment = 'test' then 'TEST-INVB-'
      else 'INVB-'
    end || v_period || '-' ||
      pg_catalog.upper(v_tenant_token) || '-' ||
      pg_catalog.lpad(v_batch_seq::text, 6, '0');
  end if;

  for v_item, v_item_index in
    select item_value, ordinality::int
    from pg_catalog.jsonb_array_elements(p_items)
      with ordinality as item_rows(item_value, ordinality)
  loop
    v_item_key := v_item ->> 'client_item_key';
    v_entity_id := pg_catalog.btrim(coalesce(v_item ->> 'entity_id', ''));
    v_department_code := pg_catalog.upper(
      pg_catalog.btrim(coalesce(v_item ->> 'department_code', ''))
    );
    v_entity_name := private.finance_income_validate_scope(
      v_tenant_id,
      v_entity_id,
      v_department_code
    );

    if coalesce(pg_catalog.btrim(v_item ->> 'buyer'), '') = '' then
      raise exception '第 % 筆發票缺少買受人', v_item_index
        using errcode = '22023';
    end if;
    if coalesce(v_item ->> 'amount', '') !~
       '^[0-9]+([.][0-9]{1,2})?$'
       or coalesce(v_item ->> 'tax', '') !~
       '^[0-9]+([.][0-9]{1,2})?$'
       or coalesce(v_item ->> 'total', '') !~
       '^[0-9]+([.][0-9]{1,2})?$' then
      raise exception '第 % 筆發票金額格式錯誤', v_item_index
        using errcode = '22003';
    end if;

    v_amount := (v_item ->> 'amount')::numeric;
    v_tax := (v_item ->> 'tax')::numeric;
    v_total := (v_item ->> 'total')::numeric;
    if pg_catalog.abs(v_total - (v_amount + v_tax)) > 0.01 then
      raise exception '第 % 筆發票未稅金額加稅額不等於含稅總額', v_item_index
        using errcode = '23514';
    end if;

    v_invoice_date := coalesce(
      nullif(v_item ->> 'invoice_date', '')::date,
      current_date
    );
    v_identifier_type := public.normalize_invoice_identifier_type(
      coalesce(v_item ->> 'invoice_identifier_type', '電子發票')
    );
    if v_identifier_type not in (
      '電子發票',
      '統一編號',
      '電子發票（載具）',
      '領據'
    ) then
      raise exception '第 % 筆發票開立方式不支援', v_item_index
        using errcode = '23514';
    end if;

    v_route := private.finance_income_validate_submission_steps(
      v_item -> 'steps',
      v_actor.id,
      v_tenant_id
    );
    v_steps := v_route -> 'steps';
    v_source_bill_id := nullif(v_item ->> 'source_bill_id', '');

    if v_source_bill_id is not null and not exists (
      select 1
      from public.bills source_bill
      where source_bill.id = v_source_bill_id
        and source_bill.tenant_id = v_tenant_id
        and source_bill.data_environment = v_environment
    ) then
      raise exception '第 % 筆發票來源繳費單不存在或跨租戶', v_item_index
        using errcode = '23503';
    end if;

    v_seq := private.finance_income_next_number(
      v_tenant_id,
      v_environment,
      'invoice',
      v_period
    );
    v_no := case
      when v_environment = 'test' then 'TEST-INV-'
      else 'INV-'
    end || v_period || '-' ||
      pg_catalog.upper(v_tenant_token) || '-' ||
      pg_catalog.lpad(v_seq::text, 6, '0');
    v_id := case
      when v_environment = 'test' then 'test_inv_'
      else 'inv_'
    end || v_period || '_' || v_tenant_token || '_' ||
      pg_catalog.lpad(v_seq::text, 6, '0');

    insert into public.invoices (
      id,
      no,
      entity_id,
      entity_name,
      buyer,
      amount,
      tax,
      total,
      invoice_date,
      status,
      description,
      department_code,
      tax_id,
      applicant,
      applicant_id,
      batch_id,
      approval_status,
      approval_step,
      steps,
      receipt_files,
      data_environment,
      invoice_identifier_type,
      invoice_item_type,
      payer_type,
      funding_source,
      service_period,
      contract_no,
      source_bill_id,
      tenant_id,
      submission_idempotency_key,
      submission_item_key,
      submission_request_digest,
      submission_actor_finance_user_id
    )
    values (
      v_id,
      v_no,
      v_entity_id,
      v_entity_name,
      pg_catalog.btrim(v_item ->> 'buyer'),
      v_amount,
      v_tax,
      v_total,
      v_invoice_date,
      'unpaid',
      nullif(pg_catalog.btrim(v_item ->> 'description'), ''),
      v_department_code,
      nullif(pg_catalog.btrim(v_item ->> 'tax_id'), ''),
      v_actor.name,
      v_actor.id,
      v_batch_id,
      v_route ->> 'approval_status',
      (v_route ->> 'approval_step')::int,
      v_steps,
      '[]'::jsonb,
      v_environment,
      v_identifier_type,
      nullif(pg_catalog.btrim(v_item ->> 'invoice_item_type'), ''),
      nullif(pg_catalog.btrim(v_item ->> 'payer_type'), ''),
      nullif(pg_catalog.btrim(v_item ->> 'funding_source'), ''),
      nullif(pg_catalog.btrim(v_item ->> 'service_period'), ''),
      nullif(pg_catalog.btrim(v_item ->> 'contract_no'), ''),
      v_source_bill_id,
      v_tenant_id,
      p_idempotency_key,
      v_item_key,
      v_digest,
      v_actor.id
    );

    v_result_rows := v_result_rows || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'client_item_key', v_item_key,
        'id', v_id,
        'no', v_no,
        'batch_id', v_batch_id,
        'approval_status', v_route ->> 'approval_status',
        'approval_step', (v_route ->> 'approval_step')::int
      )
    );
  end loop;

  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'idempotent_replay', false,
    'document_type', 'invoice',
    'idempotency_key', p_idempotency_key,
    'batch_id', v_batch_id,
    'count', pg_catalog.jsonb_array_length(v_result_rows),
    'rows', v_result_rows
  );

  perform private.finance_income_finish_operation(
    v_tenant_id,
    v_environment,
    'invoice_submit',
    p_idempotency_key,
    v_result
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_submit_bill_batch(p_idempotency_key text, p_items jsonb, p_data_environment text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_actor public.finance_users%rowtype;
  v_environment text := pg_catalog.lower(coalesce(p_data_environment, 'production'));
  v_digest text;
  v_cached jsonb;
  v_item jsonb;
  v_item_index int;
  v_item_key text;
  v_entity_id text;
  v_entity_name text;
  v_department_code text;
  v_amount numeric;
  v_due_date date;
  v_route jsonb;
  v_steps jsonb;
  v_seq bigint;
  v_batch_seq bigint;
  v_period text := pg_catalog.to_char(current_date, 'YYYYMM');
  v_tenant_token text;
  v_id text;
  v_no text;
  v_batch_id text;
  v_prepared_rows jsonb := '[]'::jsonb;
  v_result_rows jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception '請先登入後再送出繳費單'
      using errcode = '42501';
  end if;
  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test'
      using errcode = '22023';
  end if;

  v_tenant_id := public.current_tenant_id();
  select finance_user.*
    into v_actor
  from public.finance_users finance_user
  where finance_user.tenant_id = v_tenant_id
    and finance_user.auth_user_id = auth.uid()
    and finance_user.active is true
  order by finance_user.created_at, finance_user.id
  limit 1;

  if not found then
    raise exception '目前登入帳號沒有此租戶的有效財務人員身分'
      using errcode = '42501';
  end if;

  perform private.finance_income_assert_items_with_limit(p_items, 150);
  v_digest := private.finance_income_request_digest(
    pg_catalog.jsonb_build_object(
      'operation', 'bill_submit',
      'environment', v_environment,
      'items', p_items
    )
  );
  v_cached := private.finance_income_begin_operation(
    v_tenant_id,
    v_environment,
    'bill_submit',
    p_idempotency_key,
    v_digest,
    v_actor.id
  );
  if v_cached is not null then
    return v_cached || pg_catalog.jsonb_build_object(
      'idempotent_replay',
      true
    );
  end if;

  v_tenant_token := pg_catalog.replace(
    pg_catalog.left(v_tenant_id::text, 8),
    '-',
    ''
  );

  if pg_catalog.jsonb_array_length(p_items) > 1 then
    v_batch_seq := private.finance_income_next_number(
      v_tenant_id,
      v_environment,
      'bill_batch',
      v_period
    );
    v_batch_id := case
      when v_environment = 'test' then 'TEST-BILLB-'
      else 'BILLB-'
    end || v_period || '-' ||
      pg_catalog.upper(v_tenant_token) || '-' ||
      pg_catalog.lpad(v_batch_seq::text, 6, '0');
  end if;

  for v_item, v_item_index in
    select item_value, ordinality::int
    from pg_catalog.jsonb_array_elements(p_items)
      with ordinality as item_rows(item_value, ordinality)
  loop
    v_item_key := v_item ->> 'client_item_key';
    v_entity_id := pg_catalog.btrim(coalesce(v_item ->> 'entity_id', ''));
    v_department_code := pg_catalog.upper(
      pg_catalog.btrim(coalesce(v_item ->> 'department_code', ''))
    );
    v_entity_name := private.finance_income_validate_scope(
      v_tenant_id,
      v_entity_id,
      v_department_code
    );

    if coalesce(pg_catalog.btrim(v_item ->> 'item'), '') = '' then
      raise exception '第 % 筆繳費單缺少項目名稱', v_item_index
        using errcode = '22023';
    end if;
    if coalesce(pg_catalog.btrim(v_item ->> 'payer_name'), '') = '' then
      raise exception '第 % 筆繳費單缺少繳費人名稱', v_item_index
        using errcode = '22023';
    end if;
    if coalesce(v_item ->> 'amount', '') !~
       '^[0-9]+([.][0-9]{1,2})?$' then
      raise exception '第 % 筆繳費單金額格式錯誤', v_item_index
        using errcode = '22003';
    end if;

    v_amount := (v_item ->> 'amount')::numeric;
    if v_amount <= 0 then
      raise exception '第 % 筆繳費單金額必須大於零', v_item_index
        using errcode = '23514';
    end if;
    v_due_date := coalesce(
      nullif(v_item ->> 'due_date', '')::date,
      current_date
    );

    v_route := private.finance_income_validate_submission_steps(
      v_item -> 'steps',
      v_actor.id,
      v_tenant_id
    );
    v_steps := v_route -> 'steps';

    v_seq := private.finance_income_next_number(
      v_tenant_id,
      v_environment,
      'bill',
      v_period
    );
    v_no := case
      when v_environment = 'test' then 'TEST-BILL-'
      else 'BILL-'
    end || v_period || '-' ||
      pg_catalog.upper(v_tenant_token) || '-' ||
      pg_catalog.lpad(v_seq::text, 6, '0');
    v_id := case
      when v_environment = 'test' then 'test_bill_'
      else 'bill_'
    end || v_period || '_' || v_tenant_token || '_' ||
      pg_catalog.lpad(v_seq::text, 6, '0');

    -- Keep per-item validation, route resolution and number allocation in order.
    -- Stage the already validated values so the history AFTER STATEMENT trigger
    -- sees the complete batch once; every BEFORE/AFTER ROW trigger still fires.
    v_prepared_rows := v_prepared_rows || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'id', v_id,
        'no', v_no,
        'item', pg_catalog.btrim(v_item ->> 'item'),
        'item_key', nullif(pg_catalog.btrim(v_item ->> 'item_key'), ''),
        'entity_id', v_entity_id,
        'entity_name', v_entity_name,
        'amount', v_amount,
        'due_date', v_due_date,
        'method', coalesce(nullif(pg_catalog.btrim(v_item ->> 'method'), ''), '繳費單'),
        'note', nullif(pg_catalog.btrim(v_item ->> 'note'), ''),
        'status', 'unpaid',
        'applicant', v_actor.name,
        'applicant_id', v_actor.id,
        'applicant_email', v_actor.email,
        'department_code', v_department_code,
        'approval_status', v_route ->> 'approval_status',
        'approval_step', (v_route ->> 'approval_step')::int,
        'steps', v_steps,
        'payer_name', pg_catalog.btrim(v_item ->> 'payer_name'),
        'service_period', nullif(pg_catalog.btrim(v_item ->> 'service_period'), ''),
        'invoice_followup_status', 'unreviewed',
        'data_environment', v_environment,
        'batch_id', v_batch_id,
        'tenant_id', v_tenant_id,
        'submission_idempotency_key', p_idempotency_key,
        'submission_item_key', v_item_key,
        'submission_request_digest', v_digest,
        'submission_actor_finance_user_id', v_actor.id
      )
    );

    v_result_rows := v_result_rows || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'client_item_key', v_item_key,
        'id', v_id,
        'no', v_no,
        'batch_id', v_batch_id,
        'approval_status', v_route ->> 'approval_status',
        'approval_step', (v_route ->> 'approval_step')::int
      )
    );
  end loop;
  -- A single INSERT preserves all row-level business triggers while invoking
  -- the history projection's AFTER STATEMENT batch refresh only once.
  insert into public.bills (
    id, no, item, item_key, entity_id, entity_name, amount, due_date,
    method, note, status, applicant, applicant_id, applicant_email,
    department_code, approval_status, approval_step, steps, payer_name,
    service_period, invoice_followup_status, data_environment, batch_id,
    tenant_id, submission_idempotency_key, submission_item_key,
    submission_request_digest, submission_actor_finance_user_id
  )
  select
    staged.id, staged.no, staged.item, staged.item_key,
    staged.entity_id, staged.entity_name, staged.amount, staged.due_date,
    staged.method, staged.note, staged.status, staged.applicant,
    staged.applicant_id, staged.applicant_email, staged.department_code,
    staged.approval_status, staged.approval_step, staged.steps,
    staged.payer_name, staged.service_period,
    staged.invoice_followup_status, staged.data_environment,
    staged.batch_id, staged.tenant_id,
    staged.submission_idempotency_key, staged.submission_item_key,
    staged.submission_request_digest,
    staged.submission_actor_finance_user_id
  from pg_catalog.jsonb_populate_recordset(
    null::public.bills, v_prepared_rows
  ) with ordinality as staged
  order by staged.ordinality;

  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'idempotent_replay', false,
    'document_type', 'bill',
    'idempotency_key', p_idempotency_key,
    'batch_id', v_batch_id,
    'count', pg_catalog.jsonb_array_length(v_result_rows),
    'rows', v_result_rows
  );

  perform private.finance_income_finish_operation(
    v_tenant_id,
    v_environment,
    'bill_submit',
    p_idempotency_key,
    v_result
  );
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_expense_optional_permission_allows(p_tenant_id uuid, p_actor_finance_user_id text, p_permission_code text, p_context jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_member_id uuid;
  v_linked boolean := false;
  v_denied boolean := false;
  v_allowed boolean := false;
begin
  if pg_catalog.to_regclass('public.membership_users') is null
     and pg_catalog.to_regprocedure(
       'public.membership_current_user_id()'
     ) is null
     and pg_catalog.to_regprocedure(
       'public.membership_can(uuid,text,jsonb)'
     ) is null
     and pg_catalog.to_regprocedure(
       'public.membership_has_explicit_deny(uuid,text,jsonb)'
     ) is null then
    return true;
  end if;

  if pg_catalog.to_regclass('public.membership_users') is null
     or pg_catalog.to_regprocedure(
       'public.membership_current_user_id()'
     ) is null
     or pg_catalog.to_regprocedure(
       'public.membership_can(uuid,text,jsonb)'
     ) is null
     or pg_catalog.to_regprocedure(
       'public.membership_has_explicit_deny(uuid,text,jsonb)'
     ) is null then
    return false;
  end if;

  execute
    'select public.membership_current_user_id()'
    into v_member_id;
  if v_member_id is null then
    return false;
  end if;

  execute
    'select exists (
       select 1
       from public.membership_users membership_user
       where membership_user.id = $1
         and membership_user.tenant_id = $2
         and membership_user.legacy_finance_user_id = $3
         and membership_user.auth_user_id = auth.uid()
         and membership_user.status = ''active''
     )'
    into v_linked
    using v_member_id, p_tenant_id, p_actor_finance_user_id;
  if not coalesce(v_linked, false) then
    return false;
  end if;

  execute
    'select public.membership_has_explicit_deny($1, $2, $3)'
    into v_denied
    using
      v_member_id,
      p_permission_code,
      coalesce(p_context, '{}'::jsonb);
  if coalesce(v_denied, false) then
    return false;
  end if;

  execute
    'select public.membership_can($1, $2, $3)'
    into v_allowed
    using
      v_member_id,
      p_permission_code,
      coalesce(p_context, '{}'::jsonb);

  -- A complete Membership control plane is fail-closed: explicit deny and
  -- absent/revoked allow grants both block the action.  Production currently
  -- has none of these optional objects and therefore uses the legacy branch
  -- above; grants must be completed before a future Membership cut-over.
  return coalesce(v_allowed, false);
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_next_voucher_no_for_tenant(p_tenant_id uuid, p_kind text, p_voucher_date date, p_data_environment text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_kind text;
  v_year integer;
  v_next integer;
  v_environment text;
begin
  if p_tenant_id is null then
    raise exception '產生傳票號碼時缺少租戶'
      using errcode = '22023';
  end if;

  v_kind := pg_catalog.upper(
    pg_catalog.regexp_replace(
      coalesce(nullif(p_kind, ''), 'V'),
      '[^A-Z0-9]',
      '',
      'g'
    )
  );
  if v_kind = '' then
    v_kind := 'V';
  end if;
  v_year := pg_catalog.date_part(
    'year',
    coalesce(p_voucher_date, current_date)
  )::integer;
  v_environment := pg_catalog.lower(coalesce(
    nullif(p_data_environment, ''),
    'production'
  ));

  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test'
      using errcode = '22023';
  end if;

  insert into public.voucher_serials (
    tenant_id,
    data_environment,
    kind,
    year,
    last_no,
    updated_at
  )
  values (
    p_tenant_id,
    v_environment,
    v_kind,
    v_year,
    1,
    pg_catalog.now()
  )
  on conflict (data_environment, kind, year)
  do update
     set last_no = public.voucher_serials.last_no + 1,
         updated_at = pg_catalog.now()
  returning last_no into v_next;

  return v_kind || v_year::text || '-' ||
    pg_catalog.lpad(v_next::text, 5, '0');
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_assert_period_open(p_tenant_id uuid, p_data_environment text, p_entity_id text, p_posting_date date, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_tenant_id is null or coalesce(p_data_environment,'') not in ('production','test') or nullif(btrim(p_entity_id),'') is null or p_posting_date is null then
  raise exception '帳務期間檢查缺少租戶、環境、法人或日期' using errcode='22023';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('finance_period|'||p_tenant_id::text||'|'||p_data_environment||'|'||p_entity_id||'|'||to_char(p_posting_date,'YYYY-MM'),0));
 if exists(select 1 from public.period_closes c where c.tenant_id=p_tenant_id and c.data_environment=p_data_environment and c.entity_id=p_entity_id and c.period=to_char(p_posting_date,'YYYY-MM') and c.status='closed') then
  raise exception '法人 % 的 % 會計期間已關閉，禁止執行 %',p_entity_id,to_char(p_posting_date,'YYYY-MM'),coalesce(nullif(p_action,''),'帳務入帳') using errcode='23514';
 end if;
end $function$

CREATE OR REPLACE FUNCTION private.finance_ledger_period_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then
  perform private.finance_assert_period_open(old.tenant_id,old.data_environment,old.entity_id,old.entry_date,'刪除分類帳');return old;
 end if;
 if tg_op='UPDATE' then
  perform private.finance_assert_period_open(old.tenant_id,old.data_environment,old.entity_id,old.entry_date,'更正分類帳');
 end if;
 perform private.finance_assert_period_open(new.tenant_id,new.data_environment,new.entity_id,new.entry_date,'分類帳入帳');return new;
end $function$

CREATE OR REPLACE FUNCTION private.finance_income_assert_items_with_limit(p_items jsonb, p_max_items integer)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_count integer;
  v_distinct_count integer;
begin
  if p_max_items is null or p_max_items < 1 or p_max_items > 500 then
    raise exception '批次上限設定必須介於 1 到 500 筆'
      using errcode = '22023';
  end if;

  if pg_catalog.jsonb_typeof(p_items) <> 'array' then
    raise exception '批次內容必須是 JSON 陣列'
      using errcode = '22023';
  end if;

  v_count := pg_catalog.jsonb_array_length(p_items);
  if v_count < 1 or v_count > p_max_items then
    raise exception '每次批次送出必須包含 1 到 % 筆資料', p_max_items
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_items) item
    where pg_catalog.jsonb_typeof(item) <> 'object'
       or coalesce(item ->> 'client_item_key', '') !~
         '^[A-Za-z0-9][A-Za-z0-9._:-]{2,199}$'
  ) then
    raise exception
      '每筆資料都必須有 3 到 200 字元且格式有效的 client_item_key'
      using errcode = '22023';
  end if;

  select pg_catalog.count(*),
         pg_catalog.count(distinct item ->> 'client_item_key')
    into v_count, v_distinct_count
  from pg_catalog.jsonb_array_elements(p_items) item;

  if v_count <> v_distinct_count then
    raise exception '同一批次內的 client_item_key 不得重複'
      using errcode = '23505';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_assert_pending_step_assignees_active()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row jsonb := pg_catalog.to_jsonb(new);
  v_tenant_id uuid;
  v_status text;
  v_steps jsonb;
  v_assignee_id text;
begin
  v_tenant_id := nullif(v_row ->> 'tenant_id', '')::uuid;
  v_status := lower(coalesce(
    nullif(v_row ->> 'approval_status', ''),
    nullif(v_row ->> 'status', ''),
    ''
  ));
  v_steps := coalesce(v_row -> 'steps', '[]'::jsonb);

  if v_tenant_id is null
     or v_status not like 'pending%'
     or pg_catalog.jsonb_typeof(v_steps) <> 'array' then
    return new;
  end if;

  for v_assignee_id in
    select distinct nullif(step_row.step ->> 'uid', '')
    from pg_catalog.jsonb_array_elements(v_steps) step_row(step)
    where coalesce(step_row.step ->> 'a', '') = ''
      and nullif(step_row.step ->> 'uid', '') is not null
    order by 1
  loop
    perform 1
    from public.finance_users finance_user
    where finance_user.tenant_id = v_tenant_id
      and finance_user.id = v_assignee_id
      and finance_user.active is true
    for key share;

    if not found then
      raise exception '待簽人員已停用或不存在，請重新整理主管與簽核設定後再送出'
        using errcode = '23514',
              detail = 'OFFBOARDING_ASSIGNEE_NOT_ACTIVE';
    end if;
  end loop;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_auth_session_active()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid uuid;
begin
 begin sid:=nullif(auth.jwt()->>'session_id','')::uuid;exception when invalid_text_representation then return false;end;
 if sid is null or auth.uid() is null then return false;end if;
 return exists(select 1 from auth.sessions s where s.id=sid and s.user_id=auth.uid() and (s.not_after is null or s.not_after>statement_timestamp()));
end $function$

CREATE OR REPLACE FUNCTION private.finance_labor_book_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l private.finance_labor_lines_v1;p private.finance_labor_payments_v1;
 v public.vouchers;source_id text;kind text;entry jsonb;idx integer;parent_no text;
 expected_debit numeric;expected_credit numeric;begin
 if tg_table_name='vouchers' then
  if coalesce(new.request_id,'') not like 'labor:%' and coalesce(new.no,'') not like 'LACC%'
   and coalesce(new.no,'') not like 'LPAY%' then return new;end if;
  kind:=split_part(new.request_id,':',2);source_id:=split_part(new.request_id,':',3);
  if kind='accrual' then
   select * into l from private.finance_labor_lines_v1 where id::text=source_id;
   select r.no into parent_no from private.finance_labor_statements_v1 s
    join public.expense_requests r on r.id=s.request_id where s.id=l.statement_id;
   if l.id is null or l.writing_transaction is distinct from pg_current_xact_id()::text
    or l.accrual_voucher_no is distinct from new.no
    or new.voucher_date is distinct from l.service_date
    or new.entity_id is distinct from l.entity_id or new.tenant_id is distinct from l.tenant_id then
    raise exception 'LABOR_ATOMIC_ACCRUAL_REQUIRED' using errcode='42501';end if;
  elsif kind='payment' then
   select * into p from private.finance_labor_payments_v1 where id::text=source_id;
   select r.no into parent_no from private.finance_labor_statements_v1 s
    join public.expense_requests r on r.id=s.request_id where s.id=p.statement_id;
   if p.id is null or p.writing_transaction is distinct from pg_current_xact_id()::text
    or p.voucher_no is distinct from new.no or new.voucher_date is distinct from p.paid_on
    or new.entity_id is distinct from p.entity_id or new.tenant_id is distinct from p.tenant_id then
    raise exception 'LABOR_ATOMIC_PAYMENT_REQUIRED' using errcode='42501';end if;
  else raise exception 'LABOR_POSTING_SOURCE_INVALID' using errcode='42501';end if;
  if new.id is distinct from new.no or new.data_environment is distinct from 'production'
   or new.posted is distinct from true or new.posting_locked_at is null
   or new.adjusts_voucher_no is not null or new.adjustment_type is not null
   or new.total is distinct from (select sum((e->>'amt')::numeric)
    from jsonb_array_elements(new.entries) e where e->>'t'='dr')
   or (select sum(case when e->>'t'='dr' then (e->>'amt')::numeric else -(e->>'amt')::numeric end)
    from jsonb_array_elements(new.entries) e)<>0 then
   raise exception 'LABOR_ATOMIC_VOUCHER_INVALID' using errcode='42501';end if;
 else
  if coalesce(new.source_type,'')<>'external_labor'
   and coalesce(new.posting_key,'') not like 'external_labor:%'
   and coalesce(new.voucher_no,'') not like 'LACC%'
   and coalesce(new.voucher_no,'') not like 'LPAY%' then return new;end if;
  select * into v from public.vouchers where no=new.voucher_no;
  kind:=split_part(v.request_id,':',2);source_id:=split_part(v.request_id,':',3);
  if kind='accrual' then
   select * into l from private.finance_labor_lines_v1 where id::text=source_id;
   select r.no into parent_no from private.finance_labor_statements_v1 s
    join public.expense_requests r on r.id=s.request_id where s.id=l.statement_id;
   if l.id is null or l.writing_transaction is distinct from pg_current_xact_id()::text then
    raise exception 'LABOR_LEDGER_ACCRUAL_SOURCE_INVALID' using errcode='42501';end if;
  elsif kind='payment' then
   select * into p from private.finance_labor_payments_v1 where id::text=source_id;
   select r.no into parent_no from private.finance_labor_statements_v1 s
    join public.expense_requests r on r.id=s.request_id where s.id=p.statement_id;
   if p.id is null or p.writing_transaction is distinct from pg_current_xact_id()::text then
    raise exception 'LABOR_LEDGER_PAYMENT_SOURCE_INVALID' using errcode='42501';end if;
  else raise exception 'LABOR_LEDGER_SOURCE_INVALID' using errcode='42501';end if;
  if v.no is null or new.source_type is distinct from 'external_labor'
   or new.source_id is distinct from source_id or new.source_no is distinct from parent_no
   or new.reference_no is distinct from v.no or new.entry_date is distinct from v.voucher_date
   or new.tenant_id is distinct from v.tenant_id or new.entity_id is distinct from v.entity_id
   or new.data_environment is distinct from 'production'
   or new.posting_key !~ '^external_labor:(accrual|payment):[0-9a-f-]{36}:[1-9][0-9]*$' then
   raise exception 'LABOR_LEDGER_ATOMIC_SOURCE_REQUIRED' using errcode='42501';end if;
  idx:=split_part(new.posting_key,':',4)::integer;
  entry:=v.entries->(idx-1);
  expected_debit:=case when entry->>'t'='dr' then (entry->>'amt')::numeric else 0 end;
  expected_credit:=case when entry->>'t'='cr' then (entry->>'amt')::numeric else 0 end;
  if new.posting_key is distinct from 'external_labor:'||kind||':'||source_id||':'||idx
   or entry is null or new.account_code is distinct from entry->>'ac'
   or new.account_name is distinct from entry->>'an'
   or new.department_code is distinct from nullif(entry->>'dept','')
   or new.debit is distinct from expected_debit
   or new.credit is distinct from expected_credit then
   raise exception 'LABOR_LEDGER_ATOMIC_LINE_REQUIRED' using errcode='42501';end if;
 end if;return new;
end $function$

CREATE OR REPLACE FUNCTION private.finance_receipt_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then
  if old.status in ('paid','pending_receipt_review','partial') or old.cash_receipt_posted_at is not null then
   raise exception '已有收款證明或入帳的發票不可刪除，請循更正／沖銷程序' using errcode='42501';
  end if;
  return old;
 end if;
 if tg_op='INSERT' then
  if new.status in ('paid','pending_receipt_review','partial') or new.paid_at is not null
   or coalesce(new.receipt_files,'[]'::jsonb)<>'[]'::jsonb or new.receipt_submitted_at is not null
   or nullif(new.receipt_submitted_by,'') is not null or nullif(new.receipt_note,'') is not null
   or new.receipt_reviewed_at is not null or nullif(new.receipt_reviewed_by,'') is not null
   or nullif(new.receipt_review_note,'') is not null or new.cash_receipt_posted_at is not null then
   raise exception '新發票必須由正常申請及收款覆核流程建立，不可預先標記收款' using errcode='42501';
  end if;
  return new;
 end if;
 if new.status is distinct from old.status and (new.status in ('paid','pending_receipt_review','partial') or old.status in ('pending_receipt_review','paid','partial'))
  or (old.status in ('paid','partial') and (new.steps is distinct from old.steps or new.approval_status is distinct from old.approval_status or new.approval_step is distinct from old.approval_step))
  or (old.status in ('pending_receipt_review','paid','partial') and (new.amount is distinct from old.amount
   or new.total is distinct from old.total or new.tax is distinct from old.tax or new.entity_id is distinct from old.entity_id
   or new.department_code is distinct from old.department_code or new.no is distinct from old.no or new.batch_id is distinct from old.batch_id))
  or new.paid_at is distinct from old.paid_at
  or new.receipt_files is distinct from old.receipt_files
  or new.receipt_submitted_at is distinct from old.receipt_submitted_at
  or new.receipt_submitted_by is distinct from old.receipt_submitted_by
  or new.receipt_note is distinct from old.receipt_note
  or new.receipt_reviewed_at is distinct from old.receipt_reviewed_at
  or new.receipt_reviewed_by is distinct from old.receipt_reviewed_by
  or new.receipt_review_note is distinct from old.receipt_review_note
  or new.cash_receipt_posted_at is distinct from old.cash_receipt_posted_at then
   if not private.finance_receipt_write_allowed_v1(new.tenant_id,new.data_environment,new.id) then
    raise exception '收款資料必須使用會計送證明／執行長覆核交易，請更新頁面後再處理' using errcode='42501',detail='RECEIPT_ATOMIC_ACTION_REQUIRED';
   end if;
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_receipt_ledger_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if (coalesce(new.posting_key,'') like 'invoice:%:receipt:%' or coalesce(new.posting_key,'') like 'tenant:%:invoice:%:receipt:%')
  and not private.finance_receipt_write_allowed_v1(new.tenant_id,new.data_environment,new.source_id) then
  raise exception '收款分錄只能由執行長收款覆核交易建立' using errcode='42501',detail='RECEIPT_ATOMIC_ACTION_REQUIRED';
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION finance_hr_private.finance_hr_applicant_confirm(p_obligation_id uuid, p_expected_version integer, p_request_id uuid, p_hr_actor_id uuid, p_source_hash text, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o finance_hr_private.finance_hr_obligations; h text; existing finance_hr_private.finance_hr_requests; begin
 if p_request_id is null or p_hr_actor_id is null or p_expected_version is null then raise exception 'FINANCE_HR_INVALID_COMMAND'; end if;
 h:=finance_hr_private.finance_hr_hash(jsonb_build_object('id',p_obligation_id,'version',p_expected_version,'actor',p_hr_actor_id,'sourceHash',p_source_hash,'evidence',p_evidence));
 perform pg_advisory_xact_lock(hashtextextended(p_obligation_id::text,617));
 select * into o from finance_hr_private.finance_hr_obligations where obligation_id=p_obligation_id for update;
 if o.obligation_id is null or o.original_hr_applicant_id<>p_hr_actor_id or o.source_hash is distinct from p_source_hash then raise exception 'FINANCE_HR_APPLICANT_MISMATCH' using errcode='42501'; end if;
 select * into existing from finance_hr_private.finance_hr_requests where request_id=p_request_id;
 if found then if existing.operation<>'applicant_confirm' or existing.actor_id<>p_hr_actor_id::text or existing.obligation_id<>o.obligation_id or existing.payload_hash<>h then raise exception 'FINANCE_HR_REPLAY_CONFLICT'; end if; return existing.result||jsonb_build_object('replayed',true); end if;
 if o.version<>p_expected_version then raise exception 'FINANCE_HR_VERSION_CONFLICT' using errcode='40001'; end if;
 if o.stage_index<>3 or o.status<>'pending_applicant' then raise exception 'FINANCE_HR_ACTION_OUT_OF_ORDER'; end if;
 perform finance_hr_private.finance_hr_evidence(p_evidence,'applicant_confirmation');
 update finance_hr_private.finance_hr_obligations set stage_index=4,status='pending_voucher',version=version+1,updated_at=clock_timestamp() where obligation_id=o.obligation_id returning * into o;
 perform finance_hr_private.finance_hr_emit(o,'applicant_confirmation','hr',p_hr_actor_id::text,'原人資申請人',p_evidence);
 insert into finance_hr_private.finance_hr_requests(request_id,operation,actor_id,obligation_id,payload_hash,result) values(p_request_id,'applicant_confirm',p_hr_actor_id::text,o.obligation_id,h,jsonb_build_object('ok',true,'obligationId',o.obligation_id,'financeVersion',o.version,'status',o.status));
 return jsonb_build_object('ok',true,'obligationId',o.obligation_id,'financeVersion',o.version,'status',o.status,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION finance_hr_private.finance_hr_callback_claim(p_obligation_id uuid, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row record; token uuid; result jsonb:='[]'; begin
 if p_obligation_id is null or p_limit is null or p_limit not between 1 and 10 then raise exception 'FINANCE_HR_INVALID_LIMIT'; end if;
 for row in select d.event_id,b.payload from finance_hr_private.finance_hr_callback_delivery d join finance_hr_private.finance_hr_callback_outbox b using(event_id) where b.obligation_id=p_obligation_id and d.acknowledged_at is null and (d.lease_until is null or d.lease_until<now()) and not exists(select 1 from finance_hr_private.finance_hr_callback_outbox prior join finance_hr_private.finance_hr_callback_delivery pd using(event_id) where prior.obligation_id=b.obligation_id and prior.finance_version<b.finance_version and pd.acknowledged_at is null) order by b.created_at,b.event_id limit p_limit for update of d skip locked loop
  token:=gen_random_uuid(); update finance_hr_private.finance_hr_callback_delivery set lease_id=token,lease_until=now()+interval '2 minutes',attempts=attempts+1 where event_id=row.event_id;
  result:=result||jsonb_build_array(jsonb_build_object('eventId',row.event_id,'leaseId',token,'payload',row.payload));
 end loop;
 return result;
end $function$

CREATE OR REPLACE FUNCTION finance_hr_private.finance_hr_command(p_obligation_id uuid, p_expected_version integer, p_request_id uuid, p_action text, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.finance_users; o finance_hr_private.finance_hr_obligations; r finance_hr_private.finance_hr_routes; existing finance_hr_private.finance_hr_requests; h text; k text; next_status text; v public.vouchers;
begin
 a:=public.current_finance_user();
 if auth.uid() is null or a.id is null or a.auth_user_id is distinct from auth.uid() or not a.active then raise exception 'FINANCE_HR_FORBIDDEN' using errcode='42501'; end if;
 if p_request_id is null or p_action is null or p_expected_version is null then raise exception 'FINANCE_HR_INVALID_COMMAND'; end if;
 h:=finance_hr_private.finance_hr_hash(jsonb_build_object('id',p_obligation_id,'version',p_expected_version,'action',p_action,'evidence',p_evidence));
 perform pg_advisory_xact_lock(hashtextextended(p_obligation_id::text,617));
 select * into o from finance_hr_private.finance_hr_obligations where obligation_id=p_obligation_id for update;
 if o.obligation_id is null or o.tenant_id<>a.tenant_id or not finance_hr_private.finance_hr_reader(o.tenant_id,o.source_employer_id,a.id) then raise exception 'FINANCE_HR_FORBIDDEN' using errcode='42501'; end if;
 select * into r from finance_hr_private.finance_hr_routes where id=o.route_id;
 if not finance_hr_private.finance_hr_route_active(r) then raise exception 'FINANCE_HR_ROUTE_UNVERIFIED'; end if;
 select * into existing from finance_hr_private.finance_hr_requests where request_id=p_request_id;
 if found then if existing.operation<>'command' or existing.actor_id<>a.id or existing.obligation_id<>o.obligation_id or existing.payload_hash<>h then raise exception 'FINANCE_HR_REPLAY_CONFLICT'; end if; return existing.result||jsonb_build_object('replayed',true); end if;
 if o.version<>p_expected_version then raise exception 'FINANCE_HR_VERSION_CONFLICT' using errcode='40001'; end if;
 if o.stage_index not in (0,1,2,4) or o.route_snapshot->o.stage_index->>'actorId' is distinct from a.id then raise exception 'FINANCE_HR_NOT_ASSIGNEE' using errcode='42501'; end if;
 k:=case o.status when 'awaiting_payment_validation' then 'bank_batch_validation' when 'pending_bank_upload' then 'bank_upload' when 'pending_account_check' then 'accounting_review' when 'pending_cashier' then 'bank_disbursement' when 'pending_voucher' then 'posted_voucher' end;
 if p_action is distinct from k then raise exception 'FINANCE_HR_ACTION_OUT_OF_ORDER'; end if;
 perform finance_hr_private.finance_hr_evidence(p_evidence,k);
 if k in ('bank_batch_validation','bank_upload','bank_disbursement') and p_evidence->>'totalNetCents' is distinct from o.total_net_cents::text then raise exception 'FINANCE_HR_AMOUNT_MISMATCH'; end if;
 if k='posted_voucher' then
  select * into v from public.vouchers where id=p_evidence->>'voucherId' and tenant_id=o.tenant_id and entity_id=o.legal_entity_code and request_id='hr:'||o.obligation_id::text and posted is true and posted_at is not null and voided_at is null and data_environment='production' and total=(case when o.kind='contractor' then (select sum((contractor_rec.value->>'grossCents')::numeric)/100 from jsonb_array_elements(o.source_snapshot->'recipients') contractor_rec(value)) else o.total_net_cents/100.0 end) for key share;
  if v.id is null then raise exception 'FINANCE_HR_POSTED_VOUCHER_REQUIRED'; end if;
  insert into finance_hr_private.finance_hr_voucher_claims(voucher_id,obligation_id) values(v.id,o.obligation_id);
 end if;
 next_status:=case k when 'bank_batch_validation' then 'pending_bank_upload' when 'bank_upload' then 'pending_account_check' when 'accounting_review' then 'pending_cashier' when 'bank_disbursement' then 'pending_applicant' when 'posted_voucher' then 'closed' end;
 update finance_hr_private.finance_hr_obligations set version=version+1,stage_index=stage_index+case when k='bank_batch_validation' then 0 else 1 end,status=next_status,updated_at=clock_timestamp() where obligation_id=o.obligation_id returning * into o;
 perform finance_hr_private.finance_hr_emit(o,k,'finance',a.id,a.name,p_evidence);
 insert into finance_hr_private.finance_hr_requests(request_id,operation,actor_id,obligation_id,payload_hash,result) values(p_request_id,'command',a.id,o.obligation_id,h,jsonb_build_object('ok',true,'obligation',finance_hr_private.finance_hr_json(o,true)));
 return jsonb_build_object('ok',true,'obligation',finance_hr_private.finance_hr_json(o,true),'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION finance_hr_private.finance_hr_emit(o finance_hr_private.finance_hr_obligations, a text, actor_system text, actor_id text, actor_name text, evidence jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ev finance_hr_private.finance_hr_events; body jsonb; begin
 insert into finance_hr_private.finance_hr_events(obligation_id,finance_version,stage_index,action,actor_system,actor_id,actor_name,evidence) values(o.obligation_id,o.version,o.stage_index,a,actor_system,actor_id,actor_name,evidence) returning * into ev;
 body:=jsonb_build_object('schemaVersion',1,'eventId',ev.event_id,'obligationId',o.obligation_id,'flowId',o.flow_id,'sourceHash',o.source_hash,'sourceRevision',o.source_revision,'financeVersion',o.version,'stageIndex',o.stage_index,'status',o.status,'action',a,'actor',jsonb_build_object('system',actor_system,'id',actor_id,'name',actor_name),'occurredAt',ev.occurred_at);
 insert into finance_hr_private.finance_hr_callback_outbox(event_id,obligation_id,finance_version,payload) values(ev.event_id,o.obligation_id,o.version,body);
 insert into finance_hr_private.finance_hr_callback_delivery(event_id) values(ev.event_id);
end $function$

CREATE OR REPLACE FUNCTION finance_hr_private.finance_hr_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.finance_users; begin
 a:=public.current_finance_user();
 if auth.uid() is null or a.id is null or a.auth_user_id is distinct from auth.uid() or not a.active then raise exception 'FINANCE_HR_FORBIDDEN' using errcode='42501'; end if;
 if (select count(*) from finance_hr_private.finance_hr_obligations o where o.tenant_id=a.tenant_id and finance_hr_private.finance_hr_reader(o.tenant_id,o.source_employer_id,a.id))>500 then raise exception 'FINANCE_HR_RESULT_LIMIT'; end if;
 return jsonb_build_object('obligations',coalesce((select jsonb_agg(finance_hr_private.finance_hr_json(o,true) order by o.updated_at desc,o.obligation_id) from finance_hr_private.finance_hr_obligations o where o.tenant_id=a.tenant_id and finance_hr_private.finance_hr_reader(o.tenant_id,o.source_employer_id,a.id)),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION finance_hr_private.finance_hr_accounting_scope(p_tenant uuid, p_entity text, p_environment text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.finance_users;env text:=coalesce(nullif(btrim(p_environment),''),'production');begin
 if env='test' then return true;end if;
 if env<>'production' then raise exception 'FINANCE_HR_INVALID_ENVIRONMENT' using errcode='22023';end if;
 a:=public.current_finance_user();
 if exists(select 1 from finance_hr_private.finance_hr_postings p join finance_hr_private.finance_hr_obligations o using(obligation_id)
 where p.tenant_id=p_tenant and (p_entity is null or p.entity_id=p_entity)
 and (auth.uid() is null or a.id is null or a.auth_user_id is distinct from auth.uid() or a.tenant_id is distinct from p_tenant or not finance_hr_private.finance_hr_reader(o.tenant_id,o.source_employer_id,a.id)))
 or exists(select 1 from private.finance_payroll_accruals_v1 p join finance_hr_private.finance_hr_obligations o on o.obligation_id=p.obligation_id
 where p.status='posted' and p.tenant_id=p_tenant and (p_entity is null or p.entity_id=p_entity)
 and (auth.uid() is null or a.id is null or a.auth_user_id is distinct from auth.uid() or a.tenant_id is distinct from p_tenant or not finance_hr_private.finance_hr_reader(o.tenant_id,o.source_employer_id,a.id))) then
 raise exception 'FINANCE_HR_COMPLETE_REPORT_AUTHORIZATION_REQUIRED' using errcode='42501';end if;
 return true;
end $function$

