CREATE OR REPLACE FUNCTION finance_hr_private.finance_hr_post_voucher(p_obligation_id uuid, p_expected_version integer, p_request_id uuid, p_voucher_date date, p_entries jsonb, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.finance_users;o finance_hr_private.finance_hr_obligations;r finance_hr_private.finance_hr_routes;existing finance_hr_private.finance_hr_requests;
 h text;entry jsonb;canonical jsonb:='[]';name text;amount numeric;dr numeric:=0;cr numeric:=0;num text;description text;idx integer:=0;result jsonb;inner_request uuid;
begin
 a:=public.current_finance_user();
 if auth.uid() is null or a.id is null or a.auth_user_id is distinct from auth.uid() or not a.active then raise exception 'FINANCE_HR_FORBIDDEN' using errcode='42501';end if;
 if p_request_id is null or p_expected_version is null or p_voucher_date is null or jsonb_typeof(p_entries) is distinct from 'array' or jsonb_array_length(p_entries) not between 2 and 50 or octet_length(p_entries::text)>32000 then raise exception 'FINANCE_HR_INVALID_POSTING';end if;
 h:=finance_hr_private.finance_hr_hash(jsonb_build_object('id',p_obligation_id,'version',p_expected_version,'date',p_voucher_date,'entries',p_entries,'evidence',p_evidence));
 perform pg_advisory_xact_lock(hashtextextended(p_obligation_id::text,617));
 select * into o from finance_hr_private.finance_hr_obligations where obligation_id=p_obligation_id for update;
 if o.obligation_id is null or o.tenant_id<>a.tenant_id or not finance_hr_private.finance_hr_reader(o.tenant_id,o.source_employer_id,a.id) then raise exception 'FINANCE_HR_FORBIDDEN' using errcode='42501';end if;
 select * into r from finance_hr_private.finance_hr_routes where id=o.route_id;
 if not finance_hr_private.finance_hr_route_active(r) then raise exception 'FINANCE_HR_ROUTE_UNVERIFIED';end if;
 if o.route_snapshot->4->>'actorId' is distinct from a.id then raise exception 'FINANCE_HR_NOT_ASSIGNEE' using errcode='42501';end if;
 perform public.assert_accounting_actor();
 if not private.finance_expense_optional_permission_allows(o.tenant_id,a.id,'finance.accounting.subject.edit',jsonb_build_object('assignee_finance_user_id',a.id,'company_id',o.legal_entity_code,'entity_id',o.legal_entity_code,'resource_type','hr_payroll','resource_id',o.obligation_id,'workflow_step_key','accountant_final')) then raise exception 'FINANCE_HR_ACCOUNTING_PERMISSION_REQUIRED' using errcode='42501';end if;
 select * into existing from finance_hr_private.finance_hr_requests where request_id=p_request_id;
 if found then if existing.operation<>'post_voucher' or existing.actor_id<>a.id or existing.obligation_id<>o.obligation_id or existing.payload_hash<>h then raise exception 'FINANCE_HR_REPLAY_CONFLICT';end if;return existing.result||jsonb_build_object('replayed',true);end if;
 if o.version<>p_expected_version then raise exception 'FINANCE_HR_VERSION_CONFLICT' using errcode='40001';end if;
 if o.status<>'pending_voucher' or o.stage_index<>4 then raise exception 'FINANCE_HR_ACTION_OUT_OF_ORDER';end if;
 perform finance_hr_private.finance_hr_evidence(p_evidence,'posted_voucher');
 perform private.finance_assert_period_open(o.tenant_id,'production',o.legal_entity_code,p_voucher_date,'人資付款傳票入帳');
 for entry in select * from jsonb_array_elements(p_entries) loop
  if jsonb_typeof(entry) is distinct from 'object' or exists(select 1 from jsonb_object_keys(entry) k where k<>all((case when o.kind='contractor' then array['t','ac','amt','purpose'] else array['t','ac','amt'] end))) or coalesce(entry->>'t','') not in ('dr','cr') or coalesce(entry->>'amt','') !~ '^[0-9]{1,12}([.][0-9]{1,2})?$' or entry->>'ac'='1144' then raise exception 'FINANCE_HR_INVALID_ENTRY';end if;
  amount:=(entry->>'amt')::numeric;name:=private.finance_tenant_account_name(o.tenant_id,entry->>'ac');
  if amount<=0 or name is null then raise exception 'FINANCE_HR_INVALID_ACCOUNT_OR_AMOUNT';end if;
  canonical:=canonical||jsonb_build_array(jsonb_build_object('t',entry->>'t','ac',entry->>'ac','an',name,'dept','','amt',amount)||(case when o.kind='contractor' then jsonb_build_object('purpose',entry->>'purpose') else '{}'::jsonb end));
  if entry->>'t'='dr' then dr:=dr+amount;else cr:=cr+amount;end if;
 end loop;
 if exists(select 1 from private.finance_payroll_accruals_v1 p where p.obligation_id=o.obligation_id and p.status='posted' and not private.finance_payroll_settlement_accounts_v1(p.entries,canonical)) then raise exception 'FINANCE_HR_SETTLEMENT_MUST_CLEAR_ACCRUED_PAYABLE' using errcode='23514';end if;

 if o.kind='contractor' then
  if exists(select 1 from jsonb_array_elements(p_entries) x where coalesce(x->>'purpose','') not in('expense','net','withholding','supplementary') or (x->>'t'='dr') is distinct from (x->>'purpose'='expense'))
   or dr<>cr or dr is distinct from (select sum((x->>'grossCents')::numeric)/100 from jsonb_array_elements(o.source_snapshot->'recipients') x)
   or (select coalesce(sum((x->>'amt')::numeric),0) from jsonb_array_elements(p_entries) x where x->>'purpose'='net') is distinct from o.total_net_cents/100.0
   or (select coalesce(sum((x->>'amt')::numeric),0) from jsonb_array_elements(p_entries) x where x->>'purpose'='withholding') is distinct from (select sum((x->>'withholdingCents')::numeric)/100 from jsonb_array_elements(o.source_snapshot->'recipients') x)
   or (select coalesce(sum((x->>'amt')::numeric),0) from jsonb_array_elements(p_entries) x where x->>'purpose'='supplementary') is distinct from (select sum((x->>'supplementaryCents')::numeric)/100 from jsonb_array_elements(o.source_snapshot->'recipients') x)
  then raise exception 'FINANCE_HR_CONTRACTOR_GROSS_TAX_NET_REQUIRED' using errcode='23514';end if;
 else
  if dr<>cr or dr<>o.total_net_cents/100.0 then raise exception 'FINANCE_HR_ENTRIES_UNBALANCED_OR_AMOUNT_MISMATCH';end if;
 end if;

 -- Post only the net payment settlement; gross payroll accrual/deductions remain
 -- separate accounting work and are never guessed from the net amount.
 num:=private.finance_next_voucher_no_for_tenant(o.tenant_id,'HRV',p_voucher_date,'production');
 description:='人資核准付款結算 '||o.period||case o.kind when 'bonus' then ' 獎金' when 'contractor' then ' 外聘服務費' else ' 薪資' end;
 insert into finance_hr_private.finance_hr_postings(obligation_id,voucher_id,tenant_id,entity_id,actor_id,voucher_date,entries,total,description,writing_transaction) values(o.obligation_id,num,o.tenant_id,o.legal_entity_code,a.id,p_voucher_date,canonical,dr,description,pg_current_xact_id()::text);
 insert into public.vouchers(id,no,request_id,entity_id,entity_name,voucher_date,description,entries,total,creator,posted,posted_at,posting_locked_at,data_environment,tenant_id)
 values(num,num,'hr:'||o.obligation_id::text,o.legal_entity_code,o.legal_entity_code,p_voucher_date,description,canonical,dr,a.name,true,clock_timestamp(),clock_timestamp(),'production',o.tenant_id);
 for entry in select * from jsonb_array_elements(canonical) loop
  idx:=idx+1;
  insert into public.ledger_entries(entry_date,description,entity_id,department_code,debit,credit,account_code,account_name,reference_no,posting_key,source_type,source_id,source_no,voucher_no,data_environment,tenant_id)
  values(p_voucher_date,description,o.legal_entity_code,'',case when entry->>'t'='dr' then (entry->>'amt')::numeric else 0 end,case when entry->>'t'='cr' then (entry->>'amt')::numeric else 0 end,entry->>'ac',entry->>'an',num,'hr:'||o.obligation_id::text||':'||idx,'hr_payroll',o.obligation_id::text,num,num,'production',o.tenant_id);
 end loop;
 result:=finance_hr_private.finance_hr_command(o.obligation_id,o.version,gen_random_uuid(),'posted_voucher',p_evidence||jsonb_build_object('voucherId',num));
 result:=result||jsonb_build_object('voucherId',num,'voucherNo',num,'replayed',false);
 insert into finance_hr_private.finance_hr_requests(request_id,operation,actor_id,obligation_id,payload_hash,result) values(p_request_id,'post_voucher',a.id,o.obligation_id,h,result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION finance_hr_private.finance_hr_attachment_scope(p_tenant uuid, p_record_type text, p_record_no text, p_environment text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p finance_hr_private.finance_hr_postings;begin
 if p_record_type is distinct from 'vouchers' then return true;end if;
 select * into p from finance_hr_private.finance_hr_postings where tenant_id=p_tenant and voucher_id=p_record_no;
 if p.voucher_id is not null then return finance_hr_private.finance_hr_accounting_scope(p_tenant,p.entity_id,'production');end if;
 if coalesce(p_record_no,'') like 'HRV%' then raise exception 'FINANCE_HR_VOUCHER_ATTACHMENT_SOURCE_REQUIRED' using errcode='42501';end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION finance_hr_private.finance_hr_intake(p_event_id uuid, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o finance_hr_private.finance_hr_obligations; r finance_hr_private.finance_hr_routes; h text; id uuid; existing finance_hr_private.finance_hr_requests; actors jsonb; total bigint; item jsonb; source_total bigint:=0; source_rows jsonb;
begin
 if p_event_id is null or jsonb_typeof(p_envelope) is distinct from 'object' or octet_length(p_envelope::text)>1048576 then raise exception 'FINANCE_HR_INVALID_ENVELOPE'; end if;
 h:=finance_hr_private.finance_hr_hash(p_envelope); id:=(p_envelope->>'obligationId')::uuid;
 if id is null or (p_envelope->>'flowId')::uuid is null or (p_envelope->>'originalApplicantId')::uuid is null or (p_envelope->>'sourceEmployerId')::uuid is null or p_envelope->>'schemaVersion' is distinct from '1' or coalesce(p_envelope->>'kind','') not in ('monthly','bonus','contractor') or coalesce(p_envelope->>'revision','') !~ '^[1-9][0-9]{0,8}$' or coalesce(p_envelope->>'period','') !~ '^\d{4}-(0[1-9]|1[0-2])$' or coalesce(p_envelope->>'payDate','') !~ '^\d{4}-\d{2}-\d{2}$' or p_envelope->>'amountMeaning' is distinct from 'calculated_net' or jsonb_typeof(p_envelope->'source') is distinct from 'object' or p_envelope->>'sourceHash' is distinct from finance_hr_private.finance_hr_hash(p_envelope->'source') then raise exception 'FINANCE_HR_SOURCE_INVALID'; end if;
 if coalesce(p_envelope->'source'->>'totalNetCents','') !~ '^[1-9][0-9]{0,13}$' then raise exception 'FINANCE_HR_NET_AMOUNT_REQUIRED'; end if;
 total:=(p_envelope->'source'->>'totalNetCents')::bigint;
 if p_envelope->>'kind'='contractor' then
  if exists(select 1 from jsonb_object_keys(p_envelope->'source') k where k<>all(array['recipients','totalNetCents','settlementId','serviceId','taxRunId','ruleYear','ruleRevision']))
   or coalesce(p_envelope->'source'->>'settlementId','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
   or coalesce(p_envelope->'source'->>'serviceId','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
   or coalesce(p_envelope->'source'->>'taxRunId','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
   or coalesce(p_envelope->'source'->>'ruleYear','') !~ '^(19|20|21)[0-9]{2}$'
   or coalesce(p_envelope->'source'->>'ruleRevision','') !~ '^[1-9][0-9]{0,8}$' then raise exception 'FINANCE_HR_CONTRACTOR_SOURCE_INVALID';end if;
 end if;
 source_rows:=case p_envelope->>'kind' when 'monthly' then p_envelope->'source'->'lines' when 'bonus' then p_envelope->'source'->'employees' else p_envelope->'source'->'recipients' end;
 if jsonb_typeof(source_rows) is distinct from 'array' or jsonb_array_length(source_rows) not between 1 and 500 then raise exception 'FINANCE_HR_SOURCE_LINES_REQUIRED'; end if;
 for item in select * from jsonb_array_elements(source_rows) loop
  if jsonb_typeof(item) is distinct from 'object' or (p_envelope->>'kind'<>'contractor' and coalesce(item->>'employeeId','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') then raise exception 'FINANCE_HR_SOURCE_LINE_INVALID'; end if;
  if p_envelope->>'kind'='monthly' then
   if coalesce(item->>'kind','') not in ('addition','deduction') or coalesce(item->>'amountCents','') !~ '^[0-9]{1,14}$' then raise exception 'FINANCE_HR_SOURCE_LINE_INVALID'; end if;
   source_total:=source_total+(case when item->>'kind'='addition' then 1 else -1 end)*(item->>'amountCents')::bigint;
  elsif p_envelope->>'kind'='bonus' then
   if coalesce(item->>'netCents','') !~ '^[0-9]{1,14}$' or coalesce(item->>'grossCents','') !~ '^[0-9]{1,14}$' or coalesce(item->>'deductionsCents','') !~ '^[0-9]{1,14}$' or (item->>'netCents')::bigint<>(item->>'grossCents')::bigint-(item->>'deductionsCents')::bigint then raise exception 'FINANCE_HR_SOURCE_LINE_INVALID'; end if;
   source_total:=source_total+(item->>'netCents')::bigint;
  else
   if exists(select 1 from jsonb_object_keys(item) k where k<>all(array['contractorId','payeeName','incomeCode','grossCents','withholdingCents','supplementaryCents','netCents','settlementId','taxRunId']))
    or coalesce(item->>'contractorId','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    or length(btrim(coalesce(item->>'payeeName',''))) not between 1 and 200
    or coalesce(item->>'incomeCode','') not in ('50','9A','9B')
    or item->>'settlementId' is distinct from p_envelope->'source'->>'settlementId'
    or item->>'taxRunId' is distinct from p_envelope->'source'->>'taxRunId'
    or coalesce(item->>'grossCents','') !~ '^[0-9]{1,14}$'
    or coalesce(item->>'withholdingCents','') !~ '^[0-9]{1,14}$'
    or coalesce(item->>'supplementaryCents','') !~ '^[0-9]{1,14}$'
    or coalesce(item->>'netCents','') !~ '^[0-9]{1,14}$'
    then raise exception 'FINANCE_HR_CONTRACTOR_LINE_INVALID';end if;
   if (item->>'netCents')::bigint<>(item->>'grossCents')::bigint-(item->>'withholdingCents')::bigint-(item->>'supplementaryCents')::bigint then raise exception 'FINANCE_HR_CONTRACTOR_LINE_INVALID';end if;
   source_total:=source_total+(item->>'netCents')::bigint;
  end if;
 end loop;
 if source_total<>total then raise exception 'FINANCE_HR_SOURCE_TOTAL_MISMATCH'; end if;
 if p_envelope->>'kind'='monthly' and exists(select 1 from jsonb_array_elements(source_rows) x group by x->>'employeeId' having sum((case when x->>'kind'='addition' then 1 else -1 end)*(x->>'amountCents')::bigint)<0) then raise exception 'FINANCE_HR_SOURCE_NEGATIVE_NET'; end if;
 if p_envelope->>'kind'='bonus' and exists(select 1 from jsonb_array_elements(source_rows) x group by x->>'employeeId' having count(*)>1) then raise exception 'FINANCE_HR_SOURCE_DUPLICATE_EMPLOYEE'; end if;
 if p_envelope->>'kind'='contractor' and exists(select 1 from jsonb_array_elements(source_rows) x group by (x->>'contractorId')::uuid having count(*)>1) then raise exception 'FINANCE_HR_SOURCE_DUPLICATE_CONTRACTOR';end if;
 perform pg_advisory_xact_lock(hashtextextended(id::text,617));
 select * into existing from finance_hr_private.finance_hr_requests where request_id=p_event_id;
 if found then if existing.operation<>'intake' or existing.obligation_id<>id or existing.payload_hash<>h then raise exception 'FINANCE_HR_REPLAY_CONFLICT'; end if; return existing.result||jsonb_build_object('replayed',true); end if;
 select * into o from finance_hr_private.finance_hr_obligations where obligation_id=id;
 if found then
  if o.envelope_hash<>h then raise exception 'FINANCE_HR_OBLIGATION_CONFLICT'; end if;
  return jsonb_build_object('ok',true,'replayed',true,'obligationId',id,'financeVersion',o.version,'status',o.status);
 end if;
 if (select count(*) from finance_hr_private.finance_hr_routes x where x.source_employer_id=(p_envelope->>'sourceEmployerId')::uuid and x.source_applicant_id=(p_envelope->>'originalApplicantId')::uuid and finance_hr_private.finance_hr_route_active(x))<>1 then raise exception 'FINANCE_HR_ROUTE_UNVERIFIED'; end if;
 select * into r from finance_hr_private.finance_hr_routes x where x.source_employer_id=(p_envelope->>'sourceEmployerId')::uuid and x.source_applicant_id=(p_envelope->>'originalApplicantId')::uuid and finance_hr_private.finance_hr_route_active(x);
 actors:=jsonb_build_array(jsonb_build_object('key','mega_upload','actorId',r.bank_actor),jsonb_build_object('key','account_check','actorId',r.account_actor),jsonb_build_object('key','cashier','actorId',r.cashier_actor),jsonb_build_object('key','applicant','actorSystem','hr','actorId',r.source_applicant_id),jsonb_build_object('key','voucher','actorId',r.voucher_actor));
 insert into finance_hr_private.finance_hr_obligations(obligation_id,flow_id,tenant_id,source_employer_id,original_hr_applicant_id,source_revision,source_hash,envelope_hash,route_id,route_snapshot,legal_entity_code,kind,period,pay_date,source_snapshot,total_net_cents) values(id,(p_envelope->>'flowId')::uuid,r.tenant_id,r.source_employer_id,r.source_applicant_id,(p_envelope->>'revision')::integer,p_envelope->>'sourceHash',h,r.id,actors,r.legal_entity_code,p_envelope->>'kind',p_envelope->>'period',(p_envelope->>'payDate')::date,p_envelope->'source',total) returning * into o;
 perform finance_hr_private.finance_hr_emit(o,'received','transport','hr-finance-bridge','人資系統傳送服務','{}');
 insert into finance_hr_private.finance_hr_requests(request_id,operation,actor_id,obligation_id,payload_hash,result) values(p_event_id,'intake','hr-finance-bridge',id,h,jsonb_build_object('ok',true,'obligationId',id,'financeVersion',1,'status',o.status));
 return jsonb_build_object('ok',true,'replayed',false,'obligationId',id,'financeVersion',1,'status',o.status);
end $function$
